begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,pg_catalog;
select plan(27);
select ok(not has_function_privilege('anon','public.customer_account_api(text,jsonb)','EXECUTE'),'anonymous cannot call account gateway');
select ok(not has_function_privilege('authenticated','public.customer_account_api(text,jsonb)','EXECUTE'),'customers and staff cannot call account gateway');
select ok(has_function_privilege('service_role','public.customer_account_api(text,jsonb)','EXECUTE'),'server can call account gateway');
select ok(not has_table_privilege('authenticated','private.customer_accounts','SELECT'),'private customer accounts are not exposed');
select ok(not has_table_privilege('service_role','private.customer_auth_challenges','SELECT'),'server cannot read challenge table outside gateway');
select ok(not (select prosecdef from pg_proc where oid='public.customer_account_api(text,jsonb)'::regprocedure),'public wrapper is security invoker');
select ok((select relrowsecurity from pg_class where oid='private.customer_accounts'::regclass),'account table has RLS');
insert into auth.users(id,phone,phone_confirmed_at,raw_app_meta_data,raw_user_meta_data)
values('00000000-0000-4000-8000-000000000081','96559999881',now(),'{}','{"role":"admin"}');
select is((select raw_app_meta_data->>'role' from auth.users where id='00000000-0000-4000-8000-000000000081'),'customer','public phone signup never inherits manager or user-supplied role');
insert into auth.users(id,email,raw_app_meta_data) values('00000000-0000-4000-8000-000000000082','customer-gateway-role-test@barber.test','{}');
select is((select raw_app_meta_data->>'role' from auth.users where id='00000000-0000-4000-8000-000000000082'),'manager','existing business email signup is unchanged');
select is(public.customer_account_api('limit',jsonb_build_object('key',repeat('a',64),'max',1)),'true'::jsonb,'first limited action is accepted');
select is(public.customer_account_api('limit',jsonb_build_object('key',repeat('a',64),'max',1)),'false'::jsonb,'server rate limit persists across calls');
select throws_ok($$select public.customer_account_api('link','{"user_id":"00000000-0000-4000-8000-000000000082","name":"Forged","country_code":"+965","phone":"59999881","phone_e164":"+96559999881"}')$$,'P0001','ACCOUNT_UNAVAILABLE','staff identities cannot be linked as customers');
select lives_ok($$select public.customer_account_api('link','{"user_id":"00000000-0000-4000-8000-000000000081","name":"Customer Test","country_code":"+965","phone":"59999881","phone_e164":"+96559999881"}')$$,'verified phone customer links without email');
select is((select email from private.customer_accounts where user_id='00000000-0000-4000-8000-000000000081'),null,'email remains optional');
select throws_ok($$select public.customer_account_api('profile','{"user_id":"00000000-0000-4000-8000-000000000081","session_id":"00000000-0000-4000-8000-000000000099"}')$$,'P0001','AUTH_REQUIRED','profile requires live session');
select public.customer_account_api('issue','{"id":"00000000-0000-4000-8000-000000000091","purpose":"signup","phone_e164":"+96559999881","code_hash":"correct","payload":{"name":"Bound Name"}}');
select is(public.customer_account_api('consume','{"id":"00000000-0000-4000-8000-000000000091","purpose":"signup","code_hash":"wrong"}'),'null'::jsonb,'wrong code rejected');
select is((select attempts from private.customer_auth_challenges where id='00000000-0000-4000-8000-000000000091'),1,'failed attempts persist');
select is(public.customer_account_api('consume','{"id":"00000000-0000-4000-8000-000000000091","purpose":"recovery","code_hash":"correct"}'),'null'::jsonb,'challenge cannot cross purposes');
select is(public.customer_account_api('consume','{"id":"00000000-0000-4000-8000-000000000091","purpose":"signup","code_hash":"correct"}')->>'name','Bound Name','verified payload is server-bound');
select is(public.customer_account_api('consume','{"id":"00000000-0000-4000-8000-000000000091","purpose":"signup","code_hash":"correct"}'),'null'::jsonb,'successful code cannot be replayed');
select public.customer_account_api('issue','{"id":"00000000-0000-4000-8000-000000000092","purpose":"signup","phone_e164":"+96559999881","code_hash":"correct","payload":{}}');
update private.customer_auth_challenges set expires_at=now()-interval '1 second' where id='00000000-0000-4000-8000-000000000092';
select is(public.customer_account_api('consume','{"id":"00000000-0000-4000-8000-000000000092","purpose":"signup","code_hash":"correct"}'),'null'::jsonb,'expired code rejected');
select public.customer_account_api('issue','{"id":"00000000-0000-4000-8000-000000000093","purpose":"signup","phone_e164":"+96559999881","code_hash":"correct","payload":{}}');
select public.customer_account_api('consume','{"id":"00000000-0000-4000-8000-000000000093","purpose":"signup","code_hash":"wrong"}') from generate_series(1,5);
select is(public.customer_account_api('consume','{"id":"00000000-0000-4000-8000-000000000093","purpose":"signup","code_hash":"correct"}'),'null'::jsonb,'five failures lock challenge');
select public.customer_account_api('issue','{"id":"00000000-0000-4000-8000-000000000094","purpose":"recovery","phone_e164":"+96559999881","code_hash":"correct","payload":{}}');
select is(public.customer_account_api('consume','{"id":"00000000-0000-4000-8000-000000000094","purpose":"recovery","code_hash":"correct"}')->>'user_id','00000000-0000-4000-8000-000000000081','recovery binds the verified customer');
select throws_ok($$update auth.users set raw_app_meta_data='{"role":"admin"}' where id='00000000-0000-4000-8000-000000000081'$$,'P0001','Role change blocked by customer recovery guard','role cannot change during password reset');
insert into auth.sessions(id,user_id,created_at,updated_at) values('00000000-0000-4000-8000-000000000095','00000000-0000-4000-8000-000000000081',now(),now());
select lives_ok($$select public.customer_account_api('finish-reset','{"user_id":"00000000-0000-4000-8000-000000000081","guard_id":"00000000-0000-4000-8000-000000000094"}')$$,'successful recovery finishes guard');
select is((select count(*) from auth.sessions where user_id='00000000-0000-4000-8000-000000000081'),0::bigint,'recovery revokes prior sessions');
select is((select count(*) from private.customer_password_reset_guards where user_id='00000000-0000-4000-8000-000000000081'),0::bigint,'recovery releases role guard after success');
select * from finish();
rollback;
